-- alliance-for-cape-fear-trees-volunteer: https://www.acftrees.org/volunteer (checked 2026-10-21)
insert into public.participation_profiles
  (id, org_id, title, organizer, interest, area, served_place_ids, mission, work, url, source_title, extra_sources, address, address_kind, address_role, contact, effort, age, cost, access, steps, bring, followup)
values (
  'alliance-for-cape-fear-trees-volunteer',
  (select id from public.volunteer_orgs where name = 'Alliance for Cape Fear Trees'),
  'Plant and care for trees with the Alliance',
  'Alliance for Cape Fear Trees',
  'Trees & habitat',
  'Wilmington and the Lower Cape Fear area, with some events in Brunswick County (such as Leland).',
  array['us-county:37129', 'us-county:37019']::text[],
